const CLIENT_JS = "\"use strict\";\nconst $ = function(id){return document.getElementById(id);};\nconst state={tab:\"explore\",sources:[],leads:[],saved:new Set(),country:\"ALL\",stream:\"ALL\",search:\"\",sourceCountry:\"ALL\",sourceSearch:\"\"};\nfunction esc(s){return String(s).replace(/&/g,\"&amp;\").replace(/</g,\"&lt;\").replace(/>/g,\"&gt;\").replace(/\"/g,\"&quot;\").replace(/'/g,\"&#39;\");}\nfunction announce(s){const n=$(\"toast\");n.textContent=s;n.classList.add(\"visible\");clearTimeout(announce.t);announce.t=setTimeout(function(){n.classList.remove(\"visible\");},2500);}\nfunction saveLocal(){try{localStorage.setItem(\"hqventures_govradar_saved_v1\",JSON.stringify([...state.saved]));}catch(e){announce(\"Bookmarks cannot be saved in this browser mode.\");}}\nfunction tab(name){if(![\"explore\",\"sources\",\"saved\",\"about\"].includes(name))return;state.tab=name;document.querySelectorAll(\".view\").forEach(function(el){el.classList.toggle(\"hidden\",el.id!==\"view-\"+name);});document.querySelectorAll(\"[data-tab]\").forEach(function(el){const active=el.dataset.tab===name;el.classList.toggle(\"active\",active);if(el.classList.contains(\"navitem\")){if(active)el.setAttribute(\"aria-current\",\"page\");else el.removeAttribute(\"aria-current\");}});if(name===\"saved\")renderSaved();window.scrollTo({top:document.querySelector(\".stats\").getBoundingClientRect().top+window.scrollY-15,behavior:\"smooth\"});}\nfunction sourceOf(lead){return state.sources.find(function(s){return s.id===lead.sourceId;});}\nfunction leadCard(l){const src=sourceOf(l);const saved=state.saved.has(l.id);return '<article class=\"lead-card\"><div class=\"card-top\"><span class=\"country-tag\">'+esc(l.flag)+' '+esc(l.country)+'</span><span class=\"review-tag\">Needs verification</span></div><h3>'+esc(l.title)+'</h3><p class=\"authority\">'+esc(l.authority)+'</p><div class=\"tags\"><span class=\"tag\">'+esc(l.stream)+'</span><span class=\"tag\">'+esc(l.category)+'</span><span class=\"tag\">'+esc(l.region)+'</span></div><p class=\"source-note\">Imported research lead. Current vacancies, dates, citizenship rules and exam stage have not been verified.</p><div class=\"card-bottom\"><button class=\"save-btn\" type=\"button\" data-save=\"'+esc(l.id)+'\" aria-pressed=\"'+saved+'\">'+(saved?\"★ Saved\":\"☆ Save lead\")+'</button><a href=\"'+esc(src?src.url:\"#\")+'\" target=\"_blank\" rel=\"noopener noreferrer\">Check official source ↗</a></div></article>';}\nfunction renderLeads(){const q=state.search.trim().toLowerCase();const filtered=state.leads.filter(function(l){return(state.country===\"ALL\"||l.country===state.country)&&(state.stream===\"ALL\"||l.stream===state.stream||l.stream===\"Both\")&&(!q||(l.title+\" \"+l.authority+\" \"+l.region+\" \"+l.country+\" \"+l.category).toLowerCase().includes(q));});$(\"results-count\").textContent=filtered.length+\" of \"+state.leads.length+\" unverified leads\";$(\"leads-grid\").innerHTML=filtered.length?filtered.map(leadCard).join(\"\"):'<div class=\"empty\"><strong>No matches found</strong><p>Try removing a filter or exploring the official source directory.</p></div>';}\nfunction sourceCard(s){return '<article class=\"source-card\"><div class=\"source-top\"><span class=\"country-tag\">'+esc(s.flag)+' '+esc(s.country)+'</span><span class=\"tag\">'+esc(s.category)+'</span></div><h3>'+esc(s.name)+'</h3><p class=\"authority\">'+esc(s.note)+'</p><div class=\"card-bottom\"><a href=\"'+esc(s.url)+'\" target=\"_blank\" rel=\"noopener noreferrer\">Visit official site ↗</a><button type=\"button\" class=\"check-btn\" data-check=\"'+esc(s.id)+'\">Check site ↻</button></div><div class=\"check-status\" id=\"status-'+esc(s.id)+'\" aria-live=\"polite\">Not checked in this session</div></article>';}\nfunction renderSources(){const q=state.sourceSearch.trim().toLowerCase();const filtered=state.sources.filter(function(s){return(state.sourceCountry===\"ALL\"||s.country===state.sourceCountry)&&(!q||(s.name+\" \"+s.country+\" \"+s.category+\" \"+s.note).toLowerCase().includes(q));});$(\"sources-count\").textContent=filtered.length+\" of \"+state.sources.length+\" official portal links\";$(\"sources-grid\").innerHTML=filtered.length?filtered.map(sourceCard).join(\"\"):'<div class=\"empty\"><strong>No sources found</strong><p>Try a different country or search term.</p></div>';}\nfunction renderSaved(){const filtered=state.leads.filter(function(l){return state.saved.has(l.id);});$(\"saved-grid\").innerHTML=filtered.length?filtered.map(leadCard).join(\"\"):'<div class=\"empty\"><strong>No saved leads yet</strong><p>Explore opportunities and tap “Save lead” to keep them on this device.</p><button type=\"button\" class=\"primary\" data-tab=\"explore\">Explore leads →</button></div>';$(\"saved-badge\").textContent=state.saved.size;}\nasync function checkSource(id){const el=$(\"status-\"+id);if(!el)return;el.textContent=\"Checking website reachability…\";const btn=document.querySelector('[data-check=\"'+id+'\"]');if(btn)btn.disabled=true;try{const res=await fetch(\"/api/check?id=\"+encodeURIComponent(id),{headers:{\"Accept\":\"application/json\"}});const x=await res.json();el.textContent=(x.status===\"reachable\"?\"● Reachable\":x.status===\"restricted\"?\"● Site restricted automated checks\":\"● Could not confirm reachability\")+\" · \"+new Date(x.checkedAt).toLocaleTimeString();if(x.status===\"reachable\")el.style.color=\"#18875e\";else el.style.color=\"#ae7b37\";}catch(e){el.textContent=\"Unable to check source. Open the official site directly.\";el.style.color=\"#b36b40\";}finally{if(btn)btn.disabled=false;}}\nfunction populateCountries(){const countries=[...new Set(state.sources.map(function(s){return s.country;}))].sort();[\"filter-country\",\"source-country\"].forEach(function(id){const el=$(id);countries.forEach(function(c){const op=document.createElement(\"option\");op.value=c;op.textContent=c;el.appendChild(op);});});}\ndocument.addEventListener(\"click\",function(e){const t=e.target.closest(\"[data-tab],[data-save],[data-check]\");if(!t)return;if(t.dataset.tab){tab(t.dataset.tab);return;}if(t.dataset.save){if(state.saved.has(t.dataset.save))state.saved.delete(t.dataset.save);else state.saved.add(t.dataset.save);saveLocal();renderLeads();renderSaved();return;}if(t.dataset.check){checkSource(t.dataset.check);}});\n$(\"hero-explore\").addEventListener(\"click\",function(){tab(\"explore\");});$(\"hero-sources\").addEventListener(\"click\",function(){tab(\"sources\");});\n$(\"search\").addEventListener(\"input\",function(e){state.search=e.target.value;renderLeads();});$(\"filter-country\").addEventListener(\"change\",function(e){state.country=e.target.value;renderLeads();});$(\"filter-stream\").addEventListener(\"change\",function(e){state.stream=e.target.value;renderLeads();});\n$(\"reset\").addEventListener(\"click\",function(){state.search=\"\";state.country=\"ALL\";state.stream=\"ALL\";$(\"search\").value=\"\";$(\"filter-country\").value=\"ALL\";$(\"filter-stream\").value=\"ALL\";renderLeads();});\n$(\"source-search\").addEventListener(\"input\",function(e){state.sourceSearch=e.target.value;renderSources();});$(\"source-country\").addEventListener(\"change\",function(e){state.sourceCountry=e.target.value;renderSources();});\n$(\"clear-saved\").addEventListener(\"click\",function(){if(state.saved.size&&confirm(\"Remove all saved leads from this browser?\")){state.saved.clear();saveLocal();renderLeads();renderSaved();announce(\"Bookmarks cleared.\");}});\nasync function init(){try{const raw=JSON.parse(localStorage.getItem(\"hqventures_govradar_saved_v1\")||\"[]\");if(Array.isArray(raw))state.saved=new Set(raw.filter(function(v){return typeof v===\"string\";}));}catch(e){}try{const response=await fetch(\"/api/catalog\");if(!response.ok)throw Error(\"Unable to fetch catalog\");const data=await response.json();state.sources=data.sources||[];state.leads=data.leads||[];$(\"stat-sources\").textContent=state.sources.length;$(\"stat-countries\").textContent=new Set(state.sources.map(function(s){return s.country;})).size;$(\"stat-leads\").textContent=state.leads.length;$(\"stat-verified\").textContent=data.verifiedListings.length;populateCountries();renderLeads();renderSources();renderSaved();}catch(e){$(\"results-count\").textContent=\"Catalog could not be loaded\";$(\"leads-grid\").innerHTML='<div class=\"empty\"><strong>We could not load the directory</strong><p>Please refresh and try again. No sample data is being shown as live.</p></div>';}}\ninit();if(\"serviceWorker\" in navigator){window.addEventListener(\"load\",function(){navigator.serviceWorker.register(\"/sw.js\").catch(function(){});});}\n";
const SW_JS = "const NAME=\"govradar-shell-v6\";const FILES=[\"/\",\"/lite\",\"/lite.css\",\"/lite.js\",\"/lite.js?v=2.7.2\",\"/app.css\",\"/app.js\",\"/full.css\",\"/enhance.js\",\"/manifest.webmanifest\",\"/icon.svg\"];self.addEventListener(\"install\",event=>{event.waitUntil(caches.open(NAME).then(c=>c.addAll(FILES)));self.skipWaiting();});self.addEventListener(\"activate\",event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==NAME).map(k=>caches.delete(k)))));self.clients.claim();});self.addEventListener(\"fetch\",event=>{const url=new URL(event.request.url);if(event.request.method!==\"GET\"||url.origin!==location.origin||url.pathname.startsWith(\"/api/\"))return;if(!FILES.includes(url.pathname))return;event.respondWith(fetch(event.request).then(r=>{const copy=r.clone();if(r.ok)caches.open(NAME).then(c=>c.put(event.request,copy));return r;}).catch(()=>caches.match(event.request)));});";
