const PUBLIC_FOOTER = '<footer class="gg-legal-footer" style="padding:24px;text-align:center;font-size:14px"><a href="/privacy">Privacy</a> · <a href="/terms">Terms</a> · <a href="mailto:connect@yorphives.com">Contact us</a></footer>';
const POLICY_CSP = "default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'; form-action 'none'";
function policyPage(kind){
 const privacy=kind==="privacy";
 const title=privacy?"Privacy":"Terms and important information";
 const body=privacy?`
 <h2>Information saved on your device</h2><p>Saved jobs, searches, language choices and related preferences are stored in your browser. Clearing browser data or changing devices can remove them. You can remove saved items in the site or clear your browser's site data.</p>
 <h2>Using this website</h2><p>When you visit, your browser sends requests to our hosting provider. Basic technical information, such as your IP address and request details, may be processed to deliver and protect the site. Searches are sent to our server to find matching notices. Do not enter sensitive personal information in a search.</p>
 <p>We do not run email alerts on this preview. We do not use optional analytics or advertising trackers in the site code. If optional analytics are added, we will ask for your choice before using them.</p>
 <h2>Earlier community feature</h2><p>Community posting is paused. If you previously used it, your account, posts and replies may still be stored. Contact us to ask about access or deletion. Authenticated export and account deletion remain available to existing device credentials.</p>
 <h2>Contact</h2><p>For privacy questions or deletion requests, write to <a href="mailto:connect@yorphives.com">connect@yorphives.com</a>. External government websites have their own privacy policies.</p>`:`
 <h2>Check the official notice</h2><p>GlobalGovJobs is an independent directory and is not a government service. Jobs and dates can change or close early. We do not individually verify every listing. Check the original authority's notice for the closing time, eligibility, fees and how to apply.</p>
 <h2>Coverage</h2><p>Imported notices currently include UK Department for Education Teaching Vacancies. ISRO notices may appear after their source checks succeed. Other government job websites are provided as a directory; a link does not mean a vacancy is open.</p>
 <h2>Source credit</h2><p>UK Teaching Vacancies information contains public sector information licensed under the <a href="https://www.nationalarchives.gov.uk/doc/open-government-licence/version/3/">Open Government Licence v3.0</a> (© Crown copyright). We do not charge to follow a listing or charge a fee or commission for contacting, interviewing or hiring a respondent to reused listings.</p>
 <p>ISRO records, when available, are sourced from the Indian Space Research Organisation / Department of Space, Government of India, under its <a href="https://www.isro.gov.in/Website_Policy.html">website policy</a>.</p>
 <h2>Contact</h2><p>Tell us about an incorrect or broken link at <a href="mailto:connect@yorphives.com">connect@yorphives.com</a>.</p>`;
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>${title} · GlobalGovJobs</title><style>body{font:17px/1.6 system-ui,sans-serif;color:#203147;background:#f5f7fb;margin:0}main{max-width:740px;margin:32px auto;padding:24px;background:white;border-radius:16px}a{color:#234da9}h1,h2{line-height:1.25}h2{font-size:20px;margin-top:28px}p{overflow-wrap:anywhere}</style></head><body><main><p><a href="/">← Back to GlobalGovJobs</a></p><h1>${title}</h1><p>Preview information · 25 November 2026</p>${body}</main></body></html>`;
}
function respond(data, status = 200, type = "application/json; charset=utf-8", extra = {}) {
  return new Response(typeof data === "string" ? data : JSON.stringify(data), {
    status, headers: { ...SECURITY, "Content-Type": type, "Cache-Control": "public, max-age=300", ...extra }
  });
}
function JSONResponse(data, status = 200, cache = "public, max-age=300") {
  return respond(data, status, "application/json; charset=utf-8", { "Cache-Control": cache });
}
export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === "/api/collector/ingest") return handleCollectorIngest(request,env);
    if (url.pathname === "/api/collector/plan") return request.method==="GET"?serveCollectorPlan(env?.DB):JSONResponse({error:"method_not_allowed"},405,"no-store");
    if (url.pathname.startsWith("/api/moderation/")) return JSONResponse({error:"community_paused"},503,"no-store");
    if (url.pathname.startsWith("/api/community/")) {
      // Retain authenticated data export and deletion for existing members.
      if((url.pathname==="/api/community/export"&&request.method==="GET") || (["/api/community/delete-account","/api/community/delete-post"].includes(url.pathname)&&request.method==="POST"))
        return handleCommunity(request, env, url.pathname, url);
      return JSONResponse({error:"community_paused",message:"Community is not open. Existing members may request their data or deletion."},503,"no-store");
    }
    if (request.method !== "GET" && request.method !== "HEAD") {
      return JSONResponse({ error: "method_not_allowed" }, 405, "no-store");
    }
    const path = url.pathname;
    if(path==="/privacy"||path==="/terms")return respond(policyPage(path.slice(1)),200,"text/html; charset=utf-8",{"Content-Security-Policy":POLICY_CSP,"Cache-Control":"no-store","X-Robots-Tag":"noindex, nofollow"});
    if(path==="/moderation"){
      const STAFF_CSP="default-src 'none'; script-src 'self'; style-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'";
      return respond(MODERATION_HTML,200,"text/html; charset=utf-8",{"Content-Security-Policy":STAFF_CSP,"Cache-Control":"private, no-store","X-Robots-Tag":"noindex, nofollow"});
    }
    if(path==="/moderation.js")return respond(MODERATION_JS,200,"text/javascript; charset=utf-8",{"Cache-Control":"private, no-store"});
    if(path==="/portable-bookmarks.js")return respond(PORTABLE_JS,200,"text/javascript; charset=utf-8",{"Cache-Control":"public, max-age=120"});
    if (path === "/" || path === "/index.html") {
      const CLASSIC_CSP = "default-src 'none'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; font-src 'self'; connect-src 'self'; img-src 'self' data:; manifest-src 'self'; worker-src 'self'; base-uri 'self'; frame-ancestors 'none'";
      return respond(FULL_HTML.replace("</main>","</main>"+PUBLIC_FOOTER), 200, "text/html; charset=utf-8", { "Content-Security-Policy": CLASSIC_CSP, "Cache-Control": "public, max-age=120", "X-Robots-Tag":"noindex, nofollow" });
    }
    if (path === "/lite" || path === "/lite/") return respond(LITE_HTML, 200, "text/html; charset=utf-8", { "Content-Security-Policy": CSP, "Cache-Control": "public, max-age=120", "X-Robots-Tag":"noindex, nofollow" });
    if (path === "/lite.css") return respond(LITE_CSS, 200, "text/css; charset=utf-8", { "Cache-Control": "public, max-age=120" });
    if (path === "/lite.js") return respond(LITE_JS, 200, "text/javascript; charset=utf-8", { "Cache-Control": "public, max-age=120" });
    if (path === "/full.css") return respond(FULL_CSS, 200, "text/css; charset=utf-8", { "Cache-Control": "public, max-age=3600" });
    if (path === "/enhance.js") return respond(ENHANCE_JS, 200, "text/javascript; charset=utf-8", { "Cache-Control": "public, max-age=120" });
    if (path === "/official.js") return respond(OFFICIAL_UI_JS, 200, "text/javascript; charset=utf-8", { "Cache-Control": "public, max-age=120" });
    if (path === "/regional.js") return respond(REGIONAL_UI_JS, 200, "text/javascript; charset=utf-8", { "Cache-Control": "public, max-age=120" });
    if (path === "/app.css") return respond(CSS, 200, "text/css; charset=utf-8", { "Cache-Control": "public, max-age=3600" });
    if (path === "/app.js") return respond(CLIENT_JS, 200, "text/javascript; charset=utf-8", { "Cache-Control": "public, max-age=3600" });
    if (path === "/sw.js") return respond(SW_JS, 200, "text/javascript; charset=utf-8", { "Cache-Control": "no-cache", "Service-Worker-Allowed": "/" });
    if (path === "/icon.svg") return respond(ICON, 200, "image/svg+xml", { "Cache-Control": "public, max-age=86400" });
    if (path === "/manifest.webmanifest") return respond(MANIFEST, 200, "application/manifest+json");
    if (path === "/openapi.json") { const publicSpec=structuredClone(OPENAPI); publicSpec.info.version=VERSION; publicSpec.info.description="Government recruitment website directory and source-gated UK and ISRO notices. Check the original notice before applying."; delete publicSpec.paths["/api/moderation/reports"]; delete publicSpec.paths["/api/moderation/decide"]; return JSONResponse(publicSpec, 200, "public, max-age=3600"); }
    if (path === "/robots.txt") return respond("User-agent: *\nDisallow: /\n", 200, "text/plain; charset=utf-8");
    if (path === "/api/health") return JSONResponse({ status: "ok", service: "hqventures-govradar", version: VERSION, serverTime: new Date().toISOString() }, 200, "no-store");
    if(path==="/release-preview")return respond(RELEASE_PREVIEW_HTML,200,"text/html; charset=utf-8",{"Content-Security-Policy":CSP,"Cache-Control":"no-store","X-Robots-Tag":"noindex, nofollow"});
    if(path==="/release-preview.css")return respond(RELEASE_PREVIEW_CSS,200,"text/css; charset=utf-8",{"Cache-Control":"public, max-age=300"});
    if(path==="/release-preview.js")return respond(RELEASE_PREVIEW_JS,200,"application/javascript; charset=utf-8",{"Cache-Control":"public, max-age=300"});

    if (path === "/api/jurisdictions") return JSONResponse(filterSources(SOURCES,url.searchParams),200,"public, max-age=600");
    if (path === "/api/source-status") return getPortalStatus(env?.DB, SOURCES);
    if (path === "/api/notices") return serveOfficialNotices(env?.DB,url.searchParams,"approved_staging");
    if (path === "/api/release-preview/notices") return serveOfficialNotices(env?.DB,url.searchParams,"uk_only_release_preview");
    if (path === "/api/ingestion-status") return servePublicIngestionStatus(env?.DB);
    if (path === "/api/notice-changes") return serveNoticeChanges(env?.DB,url.searchParams,"approved_staging");
    if (path === "/api/catalog") return JSONResponse({ version: VERSION, catalogUpdatedAt: "2026-11-16", sources: SOURCES, leads: [], verifiedListings: [], directoryTotal: SOURCES.length, newRegionalPortals: REGIONAL_SOURCES.length, notice: "State, province, devolved, prefectural and municipal portals are directories; they are not automatically imported vacancies. Source-gated UK and ISRO records are at /api/notices. Email is not delivered." }, 200, "no-store");
    if (path === "/api/check") {
      const source = SOURCES.find(s=>s.id===url.searchParams.get("id"));
      if(!source)return JSONResponse({error:"unknown_source"},404,"no-store");
      const key=new Request(new URL("/api/check?id="+source.id,url.origin).toString());
      try {const cached=await caches.default.match(key);if(cached)return cached;}catch(e){}
      const observed=await checkPortalAndStore(source,env?.DB);
      const reply=JSONResponse({...observed,disclaimer:"Website reachability is not verification of a job opening, exam date, eligibility, admit card or result."},200,"public, max-age=900");
      try{await caches.default.put(key,reply.clone());}catch(e){}
      return reply;
    }
    return JSONResponse({ error: "not_found" }, 404, "no-store");
  },
  async scheduled(controller,env,ctx){
    // A single Cron trigger keeps three independent 3-hour source tasks
    // spaced 20 minutes apart; also tolerate old schedules during migration.
    const run=async()=>{
      const task=govradarScheduledTask(controller);
      let result;
      if(task==="uk")result=await ingestDfE(env.DB);
      else if(task==="manitoba")result=await ingestManitoba(env.DB);
      else if(task==="portals"){
        // A failure in either independent task must not prevent the other.
        const outcomes=await Promise.allSettled([runScheduledPortalChecks(env.DB,SOURCES),ingestIsro(env.DB)]);
        result={portals:outcomes[0].status,isro:outcomes[1].status};
      }
      else {console.error(JSON.stringify({event:"unrecognized_or_disabled_cron",cron:controller?.cron||""}));return;}
      await expireKnownDeadlines(env.DB);
      return result;
    };
    const task=run();
    if(ctx?.waitUntil){ctx.waitUntil(task);return;}
    await task;
  }
};
